package com.msma.tgpanel.ui

/*
 * Emoji data copied from the web panel (static/js/composer.js EMOJI_CATS, index.html QUICK_REACT / ALL_REACT), so the picker and
 * the reaction bar offer exactly the same set. Stored as space-separated strings: one list literal per emoji would exceed the
 * JVM method-size limit of a static initialiser.
 */

class EmojiCategory(val icon: String, val name: String, private val raw: String) {
    val emojis: List<String> by lazy { raw.split(' ').filter { it.isNotEmpty() } }
}

